// Normalize a request from the voice layer (Vapi/Retell tool call or end-of-call report)
// or the web-chat widget. Produces a unified { action, args, tool_call_id, channel }.
const b = $json.body || {};
let action = '', args = {}, toolCallId = '';
const tc = (b.message && (b.message.toolCalls || b.message.tool_calls) || b.toolCalls || [])[0];
if (tc) {
  action = (tc.function && tc.function.name) || tc.name || '';
  toolCallId = tc.id || '';
  let a = (tc.function && tc.function.arguments) ?? tc.arguments ?? {};
  if (typeof a === 'string') { try { a = JSON.parse(a); } catch (e) { a = {}; } }
  args = a || {};
} else if (b.message && /end-of-call/i.test(b.message.type || '')) {
  const m = b.message;
  action = 'end_of_call';
  args = { summary: m.summary || '', transcript: m.transcript || '', recording_url: m.recordingUrl || m.recording_url || '', phone: (m.customer && m.customer.number) || '', ended_reason: m.endedReason || '' };
} else {
  action = b.action || b.event || ($json.query && $json.query.action) || '';
  args = b.args || b;
  toolCallId = b.tool_call_id || b.toolCallId || '';
}
const channel = b.channel || (action === 'chat_message' ? 'chat' : 'voice');
return [{ json: { action: String(action || '').toLowerCase(), args, tool_call_id: toolCallId, channel } }];

// Compute the business-hours window (ISO) for the requested day to query the calendar.
const a = $('Normalize Request').item.json.args || {};
const tz = $env.TIMEZONE || 'America/New_York';
const openH = Number($env.BUSINESS_HOURS_START || 9);
const closeH = Number($env.BUSINESS_HOURS_END || 18);
// Resolve requested date: explicit date arg, else tomorrow.
let base = a.date || a.day || '';
let d = base ? new Date(base) : new Date($now.plus({ days: 1 }).toISO());
if (isNaN(d.getTime())) d = new Date($now.plus({ days: 1 }).toISO());
const yyyy = d.getUTCFullYear(); const mm = String(d.getUTCMonth()+1).padStart(2,'0'); const dd = String(d.getUTCDate()).padStart(2,'0');
const dayISO = `${yyyy}-${mm}-${dd}`;
return [{ json: { day: dayISO, timeMin: `${dayISO}T00:00:00`, timeMax: `${dayISO}T23:59:59`, open_h: openH, close_h: closeH, tz, tool_call_id: $('Normalize Request').item.json.tool_call_id || '' } }];

// Build open slots within business hours, skipping busy events and times too soon.
const db = $('Day Bounds').item.json;
const slotMin = Number($env.SLOT_MINUTES || 60);
const leadMin = Number($env.BOOKING_LEAD_MIN || 120);
const maxSlots = Number($env.MAX_SLOTS_OFFERED || 5);
const tz = db.tz;
const dayStart = new Date(`${db.day}T${String(db.open_h).padStart(2,'0')}:00:00`).getTime();
const dayEnd = new Date(`${db.day}T${String(db.close_h).padStart(2,'0')}:00:00`).getTime();
const earliest = $now.toMillis() + leadMin * 60000;
const busy = $('Get Calendar Events').all().map(i => i.json).filter(e => e && (e.start || e.end)).map(e => {
  const s = new Date((e.start && (e.start.dateTime || e.start.date)) || 0).getTime();
  const en = new Date((e.end && (e.end.dateTime || e.end.date)) || 0).getTime();
  return { s, en };
}).filter(b => !isNaN(b.s) && !isNaN(b.en));
const slots = [];
for (let t = dayStart; t + slotMin*60000 <= dayEnd && slots.length < maxSlots; t += slotMin*60000) {
  if (t < earliest) continue;
  const end = t + slotMin*60000;
  const overlaps = busy.some(b => t < b.en && end > b.s);
  if (overlaps) continue;
  slots.push(new Date(t).toLocaleString('en-US', { timeZone: tz, weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }));
}
const result = slots.length ? `Available times on ${new Date(dayStart).toLocaleDateString('en-US',{ timeZone: tz, weekday:'long', month:'long', day:'numeric' })}: ${slots.join('; ')}.` : `No open slots that day. Offer another day or take a message.`;
return [{ json: { tool_call_id: db.tool_call_id, _result: result, slots } }];

// Prepare a booking from the tool args.
const a = $('Normalize Request').item.json.args || {};
const tz = $env.TIMEZONE || 'America/New_York';
const slotMin = Number($env.SLOT_MINUTES || 60);
const startRaw = a.start || a.datetime || a.preferred_time || a.time || '';
const startMs = new Date(startRaw).getTime();
const start = isNaN(startMs) ? '' : new Date(startMs).toISOString();
const end = isNaN(startMs) ? '' : new Date(startMs + slotMin*60000).toISOString();
const phone = String(a.phone || a.caller_phone || '').trim();
const name = a.name || a.customer_name || '';
const email = a.email || '';
const service = a.service || a.service_type || a.reason || '';
const digits = phone.replace(/[^0-9]/g, '');
const booking_id = `${$now.toMillis()}-${digits.slice(-4)}`;
const start_human = start ? new Date(start).toLocaleString('en-US', { timeZone: tz, weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }) : 'the requested time';
const biz = $env.BUSINESS_NAME || 'us';
return [{ json: { booking_id, start_iso: start, end_iso: end, start_human, name, phone, email, service, tool_call_id: $('Normalize Request').item.json.tool_call_id || '', summary: `${service || 'Appointment'} - ${name || phone}`, description: `Booked by the AI receptionist for ${biz}.\nName: ${name}\nPhone: ${phone}\nEmail: ${email}\nService: ${service}` } }];

