try { p = typeof ai === 'string' ? JSON.parse(ai) : ai; }
catch (e) { p = { reply: 'Thanks for reaching out! A team member will follow up with you shortly.', intent: 'other', name: '', phone: '', email: '', service: '', preferred_time: '', ready_to_book: false, escalate: false, summary: 'Could not parse AI output' }; }
return [{ json: { tool_call_id: $('Normalize Request').item.json.tool_call_id || '', _result: p.reply || 'Thanks!', intent: p.intent || 'other', name: p.name || '', phone: p.phone || '', email: p.email || '', service: p.service || '', preferred_time: p.preferred_time || '', ready_to_book: !!p.ready_to_book, escalate: !!p.escalate, summary: p.summary || '' } }];

